```cpp
#include <iostream>
#include <string>
#include <regex>

// Fonction de conversion Markdown vers HTML
std::string convertMarkdownToHTML(std::string& markdown) {
    // Regroupement des balises de style
    std::regex style_regex(
        R"(?i:(?:(?:^|[^\\w\\s])|(?:[ \\t\\r\\n]+))(?:\*\*|\*\*?|___|\*\*?_)(.*?)(?:\*\*|\*\*?|___|\*\*?_)(?:(?:^|[^\\w\\s])|(?:[ \\t\\r\\n]+))):)",
        std::regex::optimize);
    std::string style_replace = "<$1>$2</$1>";

    // Regroupement des titres
    std::regex title_regex(
        R"(?i:(?:(?:^|[^\\w\\s])|(?:[ \\t\\r\\n]+))(#{1,6})(.*?)(?:(?:^|[^\\w\\s])|(?:[ \\t\\r\\n]+))):)",
        std::regex::optimize);
    std::string title_replace = "<h$1>$2</h$1>";

    // Regroupement des liens
    std::regex link_regex(R"(?i:\[(.*?)]\((.*?)\))", std::regex::optimize);
    std::string link_replace = "<a href=\"$2\">$1</a>";

    // Regroupement des listes
    std::regex list_item_regex(R"(?i:^([\\d]+|[\\w]+\\.\\s*)\s+(.*?$))", std::regex::optimize);
    std::string list_item_open = "<ul><li>";
    std::string list_item_close = "</li></ul>";

    std::string html = markdown;
    html.replace_all(style_regex, style_replace);
    html.replace_all(title_regex, title_replace);
    html.replace_all(link_regex, link_replace);

    // Conversion des listes
    size_t list_start = html.find("<ul>");
    while (list_start != std::string::npos) {
        size_t list_end = html.find("</ul>", list_start);
        size_t list_item_pos = html.find("<li>", list_start + 4);
        while (list_item_pos != std::string::npos) {
            size_t list_item_end = html.find("</li>", list_item_pos);
            html.replace(list_item_pos, list_item_end - list_item_pos + 4, list_item_open + html.substr(list_item_pos + 4, list_item_end - list_item_pos - 4) + list_item_close);
            list_item_pos = html.find("<li>", list_item_pos);
        }
        html.replace(list_start, list_end - list_start + 4, "");
        list_start = html.find("<ul>", list_start);
    }

    return html;
}

int main() {
    std::string markdown = "Hello **world**! \n\n This is a _title_. \n\n [Link](https://example.com) \n\n 1. Item 1 \n 2. Item 2 \n\n *List item 1*\n+ List item 2\n- List item 3";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

Cette fonction utilise des expressions régulières pour détecter les balises de style, les titres, les liens et les listes dans le texte Markdown, puis les remplace par les éléments HTML correspondants.

La fonction prend en entrée une référence à un std::string contenant le texte Markdown et renvoie une nouvelle std::string contenant le texte HTML. L'origine du texte Markdown n'est pas modifiée.

